import errno
import math
import re
import time


def get_sysctl(module, prefixes):
    sysctl_cmd = module.get_bin_path('sysctl')
    if not sysctl_cmd:
        raise ValueError('Unable to find sysctl')
    cmd = [sysctl_cmd]
    cmd.extend(prefixes)

    try:
        rc, out, err = module.run_command(cmd)
    except (IOError, OSError) as e:
        module.warn('Unable to read sysctl: %s' % e)
        return dict()
    if rc != 0:
        module.warn('Unable to read sysctl: %s' % (err.strip() or 'exit status %s' % rc))
        return dict()

    sysctl = dict()
    previous_key = None
    for line in out.splitlines():
        if not line:
            continue
        if line[0].isspace():
            if previous_key is None:
                module.warn('Unable to split sysctl line (%s): continuation without a key' % line)
            else:
                sysctl[previous_key] += '\n' + line
            continue
        try:
            key, value = re.split(r'\s*(?:=|:)\s*|\s+', line, maxsplit=1)
            if not key:
                raise ValueError('empty sysctl key')
        except ValueError as e:
            module.warn('Unable to split sysctl line (%s): %s' % (line, e))
            previous_key = None
            continue
        sysctl[key] = value.strip()
        previous_key = key

    return sysctl


def get_sysctl_uptime(module):
    sysctl_cmd = module.get_bin_path('sysctl')
    if not sysctl_cmd:
        raise ValueError('Unable to find sysctl')

    try:
        rc, out, err = module.run_command([sysctl_cmd, '-n', 'kern.boottime'])
    except (IOError, OSError) as e:
        if getattr(e, 'errno', None) == errno.ENOENT:
            raise ValueError('Unable to execute sysctl: %s' % e)
        module.warn('Unable to read sysctl: %s' % e)
        return {}

    if rc != 0:
        return {}

    try:
        boot_time = float(out.strip())
    except ValueError:
        return {}
    if math.isnan(boot_time) or math.isinf(boot_time):
        return {}

    return {'uptime_seconds': int(time.time() - boot_time)}

